import type { ReactElement, ReactNode } from 'react'
import { Menu as BaseMenu } from '@base-ui/react/menu'
import { Icon } from '@/lib/icon'
import { cn } from '@/lib/utils'
import styles from './Menu.module.css'

interface ItemBase {
  label: ReactNode
  /** Used for typeahead when `label` is not plain text. */
  textValue?: string
  icon?: ReactNode
  disabled?: boolean
}

/** An action, a link (`href`), or a submenu (`items`). */
export interface MenuActionItem extends ItemBase {
  type?: 'item'
  onSelect?: () => void
  href?: string
  /** Shown right-aligned, e.g. "⌘ D". Display only: it does not bind the key. */
  shortcut?: string
  /** Deletes or removes something: drawn in the danger colour. */
  isDestructive?: boolean
  /** Opens a submenu instead of acting. */
  items?: MenuEntry[]
}
export interface MenuCheckboxItem extends ItemBase {
  type: 'checkbox'
  checked?: boolean
  defaultChecked?: boolean
  onCheckedChange?: (checked: boolean) => void
}
export interface MenuRadioGroupItem {
  type: 'radio'
  label?: ReactNode
  value?: string
  defaultValue?: string
  onValueChange?: (value: string) => void
  options: { value: string; label: ReactNode; disabled?: boolean }[]
}
export interface MenuGroupItem {
  type: 'group'
  label: ReactNode
  items: MenuEntry[]
}
export interface MenuSeparator {
  type: 'separator'
}
export type MenuEntry = MenuActionItem | MenuCheckboxItem | MenuRadioGroupItem | MenuGroupItem | MenuSeparator

export interface MenuProps {
  /** The button that opens it. Its props are merged, not wrapped. */
  trigger: ReactElement
  items: MenuEntry[]
  side?: 'top' | 'right' | 'bottom' | 'left'
  align?: 'start' | 'center' | 'end'
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  className?: string
}

const text = (label: ReactNode, textValue?: string) => textValue ?? (typeof label === 'string' ? label : undefined)

function Entries({ items }: { items: MenuEntry[] }) {
  return items.map((entry, i) => {
    switch (entry.type) {
      case 'separator':
        return <BaseMenu.Separator key={i} className={styles.separator} />
      case 'group':
        return (
          <BaseMenu.Group key={i} className={styles.group}>
            <BaseMenu.GroupLabel className={styles.groupLabel}>{entry.label}</BaseMenu.GroupLabel>
            <Entries items={entry.items} />
          </BaseMenu.Group>
        )
      case 'checkbox':
        return (
          <BaseMenu.CheckboxItem
            key={i}
            label={text(entry.label, entry.textValue)}
            checked={entry.checked}
            defaultChecked={entry.defaultChecked}
            onCheckedChange={entry.onCheckedChange && ((c) => entry.onCheckedChange!(c))}
            disabled={entry.disabled}
            closeOnClick={false}
            className={styles.item}
          >
            <span className={styles.indicator}>
              <BaseMenu.CheckboxItemIndicator>
                <Icon name="check" />
              </BaseMenu.CheckboxItemIndicator>
            </span>
            <span className={styles.label}>{entry.label}</span>
          </BaseMenu.CheckboxItem>
        )
      case 'radio':
        return (
          <BaseMenu.Group key={i} className={styles.group}>
            {entry.label && <BaseMenu.GroupLabel className={styles.groupLabel}>{entry.label}</BaseMenu.GroupLabel>}
            <BaseMenu.RadioGroup
              value={entry.value}
              defaultValue={entry.defaultValue}
              onValueChange={entry.onValueChange && ((v) => entry.onValueChange!(v as string))}
            >
              {entry.options.map((o) => (
                <BaseMenu.RadioItem
                  key={o.value}
                  value={o.value}
                  label={text(o.label)}
                  disabled={o.disabled}
                  closeOnClick={false}
                  className={styles.item}
                >
                  <span className={styles.indicator}>
                    <BaseMenu.RadioItemIndicator className={styles.dot} />
                  </span>
                  <span className={styles.label}>{o.label}</span>
                </BaseMenu.RadioItem>
              ))}
            </BaseMenu.RadioGroup>
          </BaseMenu.Group>
        )
      default: {
        const content = (
          <>
            {entry.icon && (
              <span className={styles.icon} aria-hidden="true">
                {entry.icon}
              </span>
            )}
            <span className={styles.label}>{entry.label}</span>
            {entry.shortcut && (
              <kbd className={styles.shortcut} aria-hidden="true">
                {entry.shortcut}
              </kbd>
            )}
          </>
        )
        const className = cn(styles.item, entry.isDestructive && styles.destructive)
        if (entry.items) {
          return (
            <BaseMenu.SubmenuRoot key={i}>
              <BaseMenu.SubmenuTrigger label={text(entry.label, entry.textValue)} disabled={entry.disabled} className={className}>
                {content}
                <span className={styles.chevron} aria-hidden="true">
                  <Icon name="chevron-right" />
                </span>
              </BaseMenu.SubmenuTrigger>
              <Surface side="right" align="start" sideOffset={-4}>
                <Entries items={entry.items} />
              </Surface>
            </BaseMenu.SubmenuRoot>
          )
        }
        // A disabled link is an inert item: Base UI's LinkItem has no disabled state.
        if (entry.href !== undefined && !entry.disabled) {
          return (
            <BaseMenu.LinkItem key={i} href={entry.href} label={text(entry.label, entry.textValue)} className={className}>
              {content}
            </BaseMenu.LinkItem>
          )
        }
        return (
          <BaseMenu.Item
            key={i}
            label={text(entry.label, entry.textValue)}
            disabled={entry.disabled}
            onClick={entry.onSelect && (() => entry.onSelect!())}
            className={className}
          >
            {content}
          </BaseMenu.Item>
        )
      }
    }
  })
}

function Surface({
  side,
  align,
  sideOffset,
  className,
  children,
}: {
  side: MenuProps['side']
  align: MenuProps['align']
  sideOffset: number
  className?: string
  children: ReactNode
}) {
  return (
    <BaseMenu.Portal>
      <BaseMenu.Positioner className={styles.positioner} side={side} align={align} sideOffset={sideOffset}>
        <BaseMenu.Popup className={cn(styles.popup, className)}>{children}</BaseMenu.Popup>
      </BaseMenu.Positioner>
    </BaseMenu.Portal>
  )
}

export function Menu({
  trigger,
  items,
  side = 'bottom',
  align = 'start',
  open,
  defaultOpen,
  onOpenChange,
  className,
}: MenuProps) {
  return (
    <BaseMenu.Root open={open} defaultOpen={defaultOpen} onOpenChange={onOpenChange && ((next) => onOpenChange(next))}>
      <BaseMenu.Trigger render={trigger} />
      <Surface side={side} align={align} sideOffset={4} className={className}>
        <Entries items={items} />
      </Surface>
    </BaseMenu.Root>
  )
}

/* 50: the popup layer, with Select, Popover and Modal. */
.positioner {
  z-index: 50;
  outline: none;
}

/* The same surface as the Select list. */
.popup {
  box-sizing: border-box;
  min-inline-size: max(12rem, var(--anchor-width));
  max-block-size: var(--available-height);
  overflow-y: auto;
  padding: var(--space-1);
  border: 1px solid var(--border);
  border-radius: var(--radius-field);
  background: var(--popover);
  box-shadow: var(--shadow-md);
  color: var(--popover-foreground);
  font-family: var(--font-sans);
  font-size: var(--text-body);
  line-height: var(--leading-body);
  outline: none;
  transform-origin: var(--transform-origin);
  transition:
    opacity 100ms,
    scale 100ms;
}
.popup[data-starting-style],
.popup[data-ending-style] {
  opacity: 0;
  scale: 0.98;
}

.item {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-block-size: var(--space-8);
  padding: var(--space-1-5) var(--space-2);
  border-radius: var(--radius-sm);
  color: inherit;
  text-decoration: none;
  cursor: default;
  user-select: none;
  outline: none;
}

/* Highlighted: where the arrow keys or the pointer are. The submenu
   trigger keeps it while its submenu is open. */
.item[data-highlighted],
.item[data-popup-open] {
  background: var(--accent);
  color: var(--accent-foreground);
}

.item[data-disabled] {
  color: var(--muted-foreground);
  opacity: 0.6;
}

/* Text colour, not the solid: 4.5:1 on the popover and on the hover
   surface. */
.destructive {
  color: var(--danger-text);
}
.destructive[data-highlighted] {
  background: var(--danger-subtle);
  color: var(--danger-text);
}

.label {
  flex: 1;
}

.icon,
.indicator,
.chevron {
  display: inline-flex;
  flex-shrink: 0;
  align-items: center;
  justify-content: center;
  inline-size: var(--space-4);
  font-size: var(--space-4);
}

.icon {
  color: var(--muted-foreground);
}
.item[data-highlighted] .icon {
  color: inherit;
}
.destructive .icon {
  color: inherit;
}

.chevron {
  margin-inline-end: calc(var(--space-1) * -1);
  color: var(--muted-foreground);
}

/* A 6px dot for the chosen radio item. */
.dot {
  inline-size: 6px;
  block-size: 6px;
  border-radius: 9999px;
  background: currentColor;
}

.shortcut {
  margin-inline-start: var(--space-4);
  font-family: inherit;
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  color: var(--muted-foreground);
  letter-spacing: 0.05em;
}

.separator {
  block-size: 1px;
  margin: var(--space-1) calc(var(--space-1) * -1);
  background: var(--border);
}

.groupLabel {
  padding: var(--space-1-5) var(--space-2) var(--space-1);
  font-size: var(--text-body-sm);
  line-height: var(--leading-body-sm);
  font-weight: 500;
  color: var(--muted-foreground);
}

/* Items are 32px; on touch they grow to 44px. */
@media (pointer: coarse) {
  .item {
    min-block-size: 44px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .popup {
    transition: none;
  }
}
